//! `jsrt::js_regex` fragments, compiled by the `regex` crate, against
//! `fixtures/regex.json`, generated by Node 26: every BMP character for the
//! classes and for ASCII `/i`, random strings for `\b`.

mod common;

use std::collections::BTreeSet;

use common::*;
use jsrt::js_regex::*;
use jsrt::string::is_js_whitespace_char;
use regex::Regex;
use serde_json::Value;

fn unit_set(v: &Value) -> BTreeSet<u32> {
    arr(v)
        .iter()
        .map(|u| u32::try_from(int(u)).unwrap())
        .collect()
}

/// BMP characters `pattern` matches as a whole string.
fn matching_bmp(pattern: &str) -> BTreeSet<u32> {
    let re = Regex::new(&format!("^(?:{pattern})$")).unwrap();
    (0..=0xFFFF)
        .filter_map(char::from_u32)
        .filter(|c| re.is_match(c.encode_utf8(&mut [0; 4])))
        .map(u32::from)
        .collect()
}

fn all_bmp() -> BTreeSet<u32> {
    (0..=0xFFFF)
        .filter(|&u| char::from_u32(u).is_some())
        .collect()
}

#[test]
fn classes_match_node() {
    let f = fixture("regex.json");
    let s = unit_set(&f["s"]);
    let w = unit_set(&f["w"]);
    let d = unit_set(&f["d"]);
    let dot: BTreeSet<u32> = all_bmp()
        .difference(&unit_set(&f["notDot"]))
        .copied()
        .collect();
    assert_eq!(matching_bmp(WHITESPACE), s, "\\s");
    assert_eq!(
        matching_bmp(&format!("[{WHITESPACE_IN_CLASS}]")),
        s,
        "\\s in a class"
    );
    assert_eq!(
        matching_bmp(NOT_WHITESPACE),
        all_bmp().difference(&s).copied().collect(),
        "\\S"
    );
    assert_eq!(matching_bmp(WORD), w, "\\w");
    assert_eq!(
        matching_bmp(&format!("[{WORD_IN_CLASS}]")),
        w,
        "\\w in a class"
    );
    assert_eq!(
        matching_bmp(NOT_WORD),
        all_bmp().difference(&w).copied().collect(),
        "\\W"
    );
    assert_eq!(matching_bmp(DIGIT), d, "\\d");
    assert_eq!(
        matching_bmp(NOT_DIGIT),
        all_bmp().difference(&d).copied().collect(),
        "\\D"
    );
    assert_eq!(matching_bmp(DOT), dot, ".");
    let ws_chars: BTreeSet<u32> = (0..=0xFFFF)
        .filter_map(char::from_u32)
        .filter(|&c| is_js_whitespace_char(c))
        .map(u32::from)
        .collect();
    assert_eq!(ws_chars, s, "is_js_whitespace_char");
}

#[test]
fn ascii_ignore_case_matches_node() {
    let f = fixture("regex.json");
    let table = &f["ignoreCase"][0];
    for letter in ('a'..='z').chain('A'..='Z') {
        let want = unit_set(&table[letter.to_string().as_str()]);
        assert_eq!(
            matching_bmp(&format!("(?i-u:{letter})")),
            want,
            "/{letter}/i"
        );
    }
}

#[test]
fn word_boundary_matches_node() {
    let f = fixture("regex.json");
    let re = Regex::new(WORD_BOUNDARY).unwrap();
    for case in arr(&f["boundary"]) {
        let s = case[0].as_str().unwrap();
        let want: Vec<i64> = arr(&case[1]).iter().map(int).collect();
        let got: Vec<i64> = re
            .find_iter(s)
            .map(|m| i64::try_from(s[..m.start()].encode_utf16().count()).unwrap())
            .collect();
        assert_eq!(got, want, "\\b in {s:?}");
    }
}

/// The `regex` crate's own spellings disagree with node, which is why the
/// fragments exist.
#[test]
fn regex_crate_defaults_differ() {
    let f = fixture("regex.json");
    assert_ne!(matching_bmp(r"\s"), unit_set(&f["s"]));
    assert_ne!(matching_bmp(r"\w"), unit_set(&f["w"]));
    assert_ne!(matching_bmp(r"\d"), unit_set(&f["d"]));
    assert_ne!(
        matching_bmp("."),
        all_bmp()
            .difference(&unit_set(&f["notDot"]))
            .copied()
            .collect()
    );
    assert_ne!(matching_bmp("(?i:k)"), unit_set(&f["ignoreCase"][0]["k"]));
    let starts = |pattern: &str| {
        Regex::new(pattern)
            .unwrap()
            .find_iter("\u{e9}a")
            .map(|m| m.start())
            .collect::<Vec<_>>()
    };
    assert_ne!(starts(r"\b"), starts(WORD_BOUNDARY));
}
